out = {}
for name, url in [('github', 'https://github.com'), ('search', 'https://www.google.com'), ('ip_via_proxy','https://1.1.1.1')]:
    try:
        urllib.request.urlopen(url, timeout=8)
        out[name] = 'UNEXPECTED_ALLOWED'
    except Exception as error:
        out[name] = str(error)
